style.css:
@-moz-document domain("youtube.com") {
/* --- Change the color of the loaded progress bar --- */
    .html5-play-progress {
        background: #ff0055 !important; /* Change to your preferred color code */
    }

    /* --- Add a glow effect to the loaded bar --- */
    .html5-play-progress {
        box-shadow: 0px 0px 8px #ff0055 !important;
    }

    /* --- Make the progress bar thicker when hovered --- */
    .html5-video-player:hover .html5-scrub-button, 
    .html5-video-player:hover .video-progress-bar {
        height: 8px !important; 
    }

    /* --- Change the color of the buffering/load progress --- */
    .html5-load-progress {
        background: rgba(255, 255, 255, 0.4) !important;
    }

    /* --- Style the circular scrubber handle (the dot) --- */
    .ytp-scrub-button {
        background: #ffffff !important;
        border: 2px solid #ff0055 !important;
        transform: scale(1.2) !important; /* Makes it slightly larger */
    }
}
